styleText:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --bg:         #F7F7F4;
      --white:      #FFFFFF;
      --accent:     #CDB18B;
      --accent-dim: #F2E4CF;
      --dark:       #0D1117;
      --dark-2:     #1A1F2E;
      --dark-3:     #0F1520;
      --text:       #111111;
      --muted:      #6B7280;
      --muted-2:    #9CA3AF;
      --border:     rgba(0,0,0,0.07);
      --border-2:   rgba(0,0,0,0.12);
      --shadow-xs:  0 1px 3px rgba(0,0,0,0.05);
      --shadow-sm:  0 2px 10px rgba(0,0,0,0.06);
      --shadow-md:  0 8px 32px rgba(0,0,0,0.08);
      --shadow-lg:  0 20px 60px rgba(0,0,0,0.10);
      --shadow-xl:  0 40px 100px rgba(0,0,0,0.12);
      --radius-sm:  10px;
      --radius-md:  16px;
      --radius-lg:  24px;
      --radius-xl:  32px;
      --radius-full:9999px;
    }
    html { scroll-behavior: smooth; }
    body { font-family: 'Inter', sans-serif; background: var(--bg); color: var(--text); line-height: 1.6; overflow-x: hidden; -webkit-font-smoothing: antialiased; }
    a { text-decoration: none; color: inherit; }

    @keyframes fadeInUp { from { opacity:0; transform:translateY(24px);} to { opacity:1; transform:translateY(0);} }
    @keyframes pulse-dot { 0%,100%{opacity:1;transform:scale(1);} 50%{opacity:.5;transform:scale(.85);} }
    .fade-in-up { animation: fadeInUp 0.7s cubic-bezier(.22,1,.36,1) both; }
    .d1{animation-delay:.1s;} .d2{animation-delay:.2s;} .d3{animation-delay:.3s;} .d4{animation-delay:.4s;}

    .container { width:100%; max-width:1200px; margin:0 auto; padding:0 32px; }
    .section { padding:100px 0; }
    .eyebrow { display:inline-flex;align-items:center;gap:7px;font-size:11px;font-weight:600;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);margin-bottom:18px; }
    .eyebrow-dot { width:6px;height:6px;border-radius:50%;background:var(--accent);animation:pulse-dot 2s ease infinite; }

    /* Buttons */
    .btn { display:inline-flex;align-items:center;gap:8px;border-radius:var(--radius-full);font-family:'Inter',sans-serif;font-weight:600;font-size:14px;cursor:pointer;transition:all .2s cubic-bezier(.22,1,.36,1);border:none;white-space:nowrap; }
    .btn-primary { background:var(--dark);color:#fff;padding:13px 28px;box-shadow:0 2px 8px rgba(0,0,0,.15); }
    .btn-primary:hover { background:var(--dark-2);transform:translateY(-2px);box-shadow:0 8px 24px rgba(0,0,0,.2); }
    .btn-accent  { background:var(--accent);color:var(--dark);padding:13px 28px;box-shadow:0 2px 8px rgba(205,177,139,.3); }
    .btn-accent:hover { background:#dac09e;transform:translateY(-2px);box-shadow:0 8px 24px rgba(205,177,139,.4); }
    .btn-outline { background:transparent;color:var(--text);padding:12px 24px;border:1.5px solid var(--border-2); }
    .btn-outline:hover { background:var(--white);color:#0D1117 !important;transform:translateY(-1px);box-shadow:var(--shadow-sm); }
    .btn-outline-light { background:transparent;color:rgba(255,255,255,.75);padding:12px 24px;border:1.5px solid rgba(255,255,255,.2); }
    .btn-outline-light:hover { background:rgba(255,255,255,.08); }

    /* ── Navbar ── */
    .navbar { position:fixed;top:0;left:0;right:0;z-index:1000;padding:0 40px;height:64px;display:flex;align-items:center;justify-content:space-between;background:rgba(247,247,244,.82);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);border-bottom:1px solid var(--border); }
    .nav-logo { display:flex;align-items:center;gap:9px;font-weight:800;font-size:18px;letter-spacing:-.03em; }
    .nav-logo-icon { width:30px;height:30px;background:var(--dark);border-radius:8px;display:flex;align-items:center;justify-content:center; }
    .nav-logo-icon svg { width:16px;height:16px; }
    .nav-links { display:flex;align-items:center;gap:2px;list-style:none; }
    .nav-links a { font-size:13px;font-weight:500;color:var(--muted);padding:7px 11px;border-radius:var(--radius-full);transition:all .15s;display:flex;align-items:center;gap:3px; }
    .nav-links a:hover,.nav-links a.active { color:var(--text);background:rgba(0,0,0,.04); }
    .nav-links a.active { color:var(--text);font-weight:600;background:rgba(0,0,0,.06); }
    .nav-actions { display:flex;align-items:center;gap:10px; }
    .nav-chevron { font-size:9px;opacity:.45; }
    .nav-item { position:relative;list-style:none; }
    .nav-item.has-mega:hover .nav-chevron,
    .nav-item.has-mega.mega-open .nav-chevron { transform:rotate(180deg);opacity:.7; }
    .mega-panel { position:fixed;top:64px;left:50%;transform:translateX(-50%) translateY(-6px);background:var(--white);border:1px solid var(--border-2);border-radius:var(--radius-lg);box-shadow:0 8px 16px rgba(0,0,0,.06),0 24px 64px rgba(0,0,0,.10);padding:24px;opacity:0;pointer-events:none;transition:opacity .18s ease,transform .18s ease;z-index:999; }
    .nav-item.has-mega:hover .mega-panel,
    .nav-item.has-mega.mega-open .mega-panel {
      opacity: 1;
      pointer-events: auto;
      transform: translateX(-50%) translateY(0);
    }
    .mega-products  { width:1040px; }
    .mega-solutions { width:680px; }
    .mega-platform  { width:680px; }
    /* Thin top accent bar */
    .mega-panel::before { content:'';position:absolute;top:0;left:24px;right:24px;height:2px;background:var(--accent);border-radius:0 0 2px 2px;opacity:.6; }
    /* Transparent hover bridge — prevents gap closing the menu */
    .mega-panel::after {
      content: '';
      position: absolute;
      top: -18px; left: 0; right: 0;
      height: 18px;
    }

    /* Hightouch-style column mega */
    .mega-cols { display:flex; align-items:flex-start; gap:0; }
    .mega-col {
      flex:1; padding:0 28px;
      border-right:1px solid var(--border-2);
      min-width:0;
    }
    .mega-col:first-child { padding-left:0; }
    .mega-col:last-child  { border-right:none; }

    .mega-col-label {
      font-size:10px; font-weight:700; letter-spacing:.1em;
      text-transform:uppercase; color:var(--muted);
      margin-bottom:16px; padding-bottom:12px;
      border-bottom:1px solid var(--border-2);
      white-space:nowrap;
    }
    .mega-col-link {
      display:block; font-size:14px; color:var(--text);
      text-decoration:none; padding:7px 0; font-weight:500;
      transition:color .15s; white-space:nowrap;
    }
    .mega-col-link:hover { color:var(--accent); }

    .mega-col-badge {
      font-size:9px; font-weight:700; letter-spacing:.05em;
      text-transform:uppercase; color:var(--accent);
      background:rgba(205,177,139,.15); border-radius:3px;
      padding:2px 5px; margin-left:6px; vertical-align:middle;
    }

    /* Featured column */
    .mega-col-featured { flex:0 0 200px !important; padding:0 0 0 28px !important; border-right:none !important; }
    .mega-featured-img {
      width:100%; height:110px; border-radius:var(--radius-sm);
      overflow:hidden; margin-bottom:12px;
    }
    .mega-featured-img img { width:100%; height:100%; object-fit:cover; }
    .mega-featured-desc {
      font-size:12.5px; color:var(--muted); line-height:1.65; margin-bottom:12px;
    }
    .mega-featured-link {
      font-size:12.5px; font-weight:600; color:var(--text);
      text-decoration:none; display:flex; align-items:center; gap:4px;
    }
    .mega-featured-link:hover { color:var(--accent); }

    /* ── Blog Hero ── */
    .blog-hero {
      background:var(--bg);
      min-height:80vh;
      display:flex;
      align-items:center;
      padding:100px 0;
      text-align:center;
      position:relative;
      overflow:hidden;
    }
    .blog-hero-bg { position:absolute;inset:0;z-index:0; }
    .blog-hero-bg img { width:100%;height:100%;object-fit:cover;object-position:center top; }
    .blog-hero .container { position:relative;z-index:1; }
    .blog-hero-badge {
      display:inline-flex;align-items:center;gap:7px;
      background:var(--white);border:1px solid var(--border-2);
      border-radius:var(--radius-full);padding:6px 16px;
      font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;
      color:var(--muted);margin-bottom:24px;
      box-shadow:var(--shadow-xs);
    }
    .blog-hero h1 {
      font-size:clamp(36px,5vw,64px);font-weight:900;line-height:1.05;letter-spacing:-.04em;
      color:var(--text);margin-bottom:18px;
    }
    .blog-hero h1 em { font-style:italic;font-family:'DM Serif Display',serif;font-weight:400;color:var(--text); }
    .blog-hero p {
      font-size:17px;color:var(--muted);max-width:480px;margin:0 auto 40px;line-height:1.75;
    }
    /* Search bar */
    .blog-search {
      display:flex;align-items:center;max-width:480px;margin:0 auto;
      background:var(--white);border:1.5px solid var(--border-2);border-radius:var(--radius-full);
      padding:6px 6px 6px 20px;box-shadow:var(--shadow-sm);
      transition:border-color .2s,box-shadow .2s;
    }
    .blog-search:focus-within { border-color:var(--accent);box-shadow:0 0 0 3px rgba(205,177,139,.15); }
    .blog-search input {
      flex:1;border:none;outline:none;font-family:'Inter',sans-serif;
      font-size:14px;font-weight:500;color:var(--text);background:transparent;
    }
    .blog-search input::placeholder { color:var(--muted-2); }
    .blog-search-btn {
      background:var(--dark);color:#fff;border:none;border-radius:var(--radius-full);
      padding:9px 22px;font-size:13px;font-weight:600;cursor:pointer;
      transition:background .2s;white-space:nowrap;
    }
    .blog-search-btn:hover { background:var(--dark-2); }

    /* ── Blog Grid Section ── */
    .blog-section { padding:72px 0 100px; background:var(--bg); }
    .blog-top-label {
      font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;
      color:var(--muted);margin-bottom:24px;
    }
    /* Filter tabs */
    .blog-filters {
      display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:48px;
    }
    .blog-filter-btn {
      padding:8px 20px;border-radius:var(--radius-full);font-size:13px;font-weight:600;
      cursor:pointer;border:1.5px solid var(--border-2);background:var(--white);
      color:var(--muted);transition:all .18s;
    }
    .blog-filter-btn:hover { border-color:rgba(0,0,0,.18);color:var(--text); }
    .blog-filter-btn.active { background:var(--dark);color:#fff;border-color:var(--dark); }

    /* Blog grid */
    .blog-grid {
      display:grid;grid-template-columns:repeat(3,1fr);gap:28px;
    }
    .blog-card {
      background:var(--white);border-radius:var(--radius-lg);overflow:hidden;
      border:1px solid var(--border);transition:all .25s cubic-bezier(.22,1,.36,1);
      display:flex;flex-direction:column;cursor:pointer;
    }
    .blog-card:hover { transform:translateY(-5px);box-shadow:var(--shadow-lg);border-color:transparent; }
    .blog-card-img {
      height:200px;position:relative;overflow:hidden;
    }
    .grad-tan    { background:linear-gradient(135deg,#e8d5b7 0%,#f5ebe0 100%); }
    .grad-blue   { background:linear-gradient(135deg,#c9d8f0 0%,#e8f0fd 100%); }
    .grad-green  { background:linear-gradient(135deg,#c2ddc5 0%,#e5f2e7 100%); }
    .grad-purple { background:linear-gradient(135deg,#d4c8f0 0%,#ede8fb 100%); }
    .grad-coral  { background:linear-gradient(135deg,#f0c8c2 0%,#fbe8e5 100%); }
    .grad-slate  { background:linear-gradient(135deg,#c8d4dc 0%,#e5ecf0 100%); }
    .blog-card-img-inner {
      width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-size:48px;
    }
    .blog-card-cat {
      position:absolute;top:14px;left:14px;
      font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;
      background:rgba(255,255,255,.92);color:var(--text);
      padding:4px 12px;border-radius:var(--radius-full);
      box-shadow:0 1px 4px rgba(0,0,0,.08);
    }
    .blog-card-body { padding:22px 24px 24px;flex:1;display:flex;flex-direction:column; }
    .blog-card-title {
      font-size:16px;font-weight:800;letter-spacing:-.02em;color:var(--text);
      line-height:1.35;margin-bottom:10px;
      transition:color .15s;
    }
    .blog-card:hover .blog-card-title { color:var(--dark); }
    .blog-card-excerpt {
      font-size:13px;color:var(--muted);line-height:1.7;flex:1;margin-bottom:20px;
    }
    .blog-card-footer {
      display:flex;align-items:center;justify-content:space-between;
      padding-top:16px;border-top:1px solid var(--border);
    }
    .blog-card-author { display:flex;align-items:center;gap:9px; }
    .blog-card-avatar {
      width:30px;height:30px;border-radius:50%;
      display:flex;align-items:center;justify-content:center;
      font-size:12px;font-weight:700;color:#fff;flex-shrink:0;
    }
    .blog-card-author-name { font-size:12px;font-weight:600;color:var(--text); }
    .blog-card-read-time { font-size:11.5px;color:var(--muted-2);font-weight:500; }

    /* ── Pagination ── */
    .blog-pagination {
      display:flex;align-items:center;justify-content:center;gap:8px;margin-top:52px;
    }
    .blog-page-btn, .blog-page-arrow {
      width:38px;height:38px;border-radius:var(--radius-sm);
      border:1.5px solid var(--border-2);background:var(--white);
      color:var(--text);font-size:14px;font-weight:600;
      cursor:pointer;transition:all .15s;
      display:flex;align-items:center;justify-content:center;
      font-family:'Inter',sans-serif;
    }
    .blog-page-btn:hover  { border-color:var(--accent);color:var(--accent); }
    .blog-page-arrow:hover { border-color:var(--accent);color:var(--accent); }
    .blog-page-btn.active { background:var(--dark);color:#fff;border-color:var(--dark); }
    .blog-page-arrow:disabled { opacity:.35;cursor:not-allowed;pointer-events:none; }
    .blog-page-arrow { font-size:18px; }

    /* ── Newsletter CTA ── */
    .newsletter-section {
      background:var(--dark);
      padding:80px 0;
      position:relative;overflow:hidden;
    }
    .newsletter-section::before {
      content:'';position:absolute;inset:0;
      background:radial-gradient(ellipse 70% 80% at 50% 50%, rgba(205,177,139,.08) 0%, transparent 70%);
      pointer-events:none;
    }
    .newsletter-section .container { position:relative;z-index:1;text-align:center; }
    .newsletter-section h2 {
      font-size:clamp(28px,4vw,48px);font-weight:900;letter-spacing:-.04em;
      color:#fff;margin-bottom:14px;line-height:1.1;
    }
    .newsletter-section h2 em { font-style:italic;font-family:'DM Serif Display',serif;font-weight:400;color:var(--accent); }
    .newsletter-section p { font-size:15px;color:rgba(255,255,255,.45);margin-bottom:36px; }
    .newsletter-form {
      display:flex;align-items:center;max-width:460px;margin:0 auto;
      background:rgba(255,255,255,.06);border:1.5px solid rgba(255,255,255,.12);
      border-radius:var(--radius-full);padding:6px 6px 6px 22px;
      transition:border-color .2s,box-shadow .2s;
    }
    .newsletter-form:focus-within { border-color:rgba(205,177,139,.5);box-shadow:0 0 0 3px rgba(205,177,139,.1); }
    .newsletter-form input {
      flex:1;border:none;outline:none;font-family:'Inter',sans-serif;
      font-size:14px;color:#fff;background:transparent;
    }
    .newsletter-form input::placeholder { color:rgba(255,255,255,.3); }
    .newsletter-form button {
      background:var(--accent);color:var(--dark);border:none;border-radius:var(--radius-full);
      padding:10px 24px;font-size:13px;font-weight:700;cursor:pointer;
      transition:background .2s;white-space:nowrap;
    }
    .newsletter-form button:hover { background:#dac09e; }

    /* ── Footer ── */
    .footer {
      background:var(--dark);color:rgba(255,255,255,.6);
      position:relative;overflow:hidden;
      padding-top:0;
    }
    .footer-bg { position:absolute;inset:0;z-index:0;opacity:.35; }
    .footer-bg img { width:100%;height:100%;object-fit:cover; }
    .footer > .container { position:relative;z-index:1; }
    .footer-grid { display:grid;grid-template-columns:2fr 1fr 1fr 1fr 1fr;gap:48px;padding-bottom:48px; }
    .footer-brand p { font-size:13px;color:rgba(255,255,255,.4);line-height:1.7;margin-top:14px;max-width:220px; }
    .footer-brand .nav-logo { color:#fff; }
    .footer-col-title { font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:rgba(255,255,255,.3);margin-bottom:16px; }
    .footer-col ul { list-style:none;display:flex;flex-direction:column;gap:10px; }
    .footer-col a { font-size:13px;color:rgba(255,255,255,.5);transition:color .15s; }
    .footer-col a:hover { color:#fff; }
    .footer-bottom { border-top:1px solid rgba(255,255,255,.07);padding:24px 0;display:flex;align-items:center;justify-content:space-between; }
    .footer-bottom-text { font-size:12px;color:rgba(255,255,255,.25); }
    .footer-socials { display:flex;gap:8px; }
    .footer-social { width:32px;height:32px;border-radius:8px;background:rgba(255,255,255,.06);display:flex;align-items:center;justify-content:center;font-size:12px;cursor:pointer;transition:background .15s; }
    .footer-social:hover { background:rgba(255,255,255,.12); }

    @media(max-width:1024px) { .blog-grid { grid-template-columns:repeat(2,1fr); } }
    @media(max-width:768px) { .navbar { padding:0 20px; } .nav-links { display:none; } .container { padding:0 20px; } .blog-grid { grid-template-columns:1fr; } .footer-grid { grid-template-columns:1fr; } }

/* ── FAQ ── */
.faq-header-row { display:flex;align-items:flex-start;justify-content:space-between;gap:40px;margin-bottom:48px; }
.faq-header-left { max-width:700px; }
.faq-header-left h2 { font-size:clamp(26px,3vw,38px);font-weight:800;letter-spacing:-.03em;color:var(--text);line-height:1.15;margin-bottom:12px; }
.faq-header-left p { font-size:14px;color:var(--muted);line-height:1.7;white-space:nowrap; }
.faq-view-all { flex-shrink:0;padding:10px 22px;border-radius:var(--radius-full);font-size:13px;font-weight:600;color:var(--text);border:1.5px solid var(--border-2);background:var(--white);cursor:pointer;transition:all .2s;white-space:nowrap;text-decoration:none; }
.faq-view-all:hover { background:var(--bg);border-color:rgba(0,0,0,.15); }
.faq-cols { display:grid;grid-template-columns:1fr 1fr;gap:0 48px; }
.faq-item { border-bottom:1px solid var(--border-2);overflow:hidden; }
.faq-item:first-child { border-top:1px solid var(--border-2); }
.faq-q { display:flex;align-items:center;justify-content:space-between;gap:16px;padding:18px 0;cursor:pointer;font-size:14px;font-weight:600;color:var(--text);letter-spacing:-.01em;user-select:none; }
.faq-icon { width:26px;height:26px;border-radius:50%;background:var(--bg);border:1.5px solid var(--border-2);display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:14px;font-weight:400;color:var(--muted);transition:all .2s;line-height:1; }
.faq-item.open .faq-icon { background:var(--dark);border-color:var(--dark);color:#fff; }
.faq-a { font-size:13.5px;color:var(--muted);line-height:1.75;max-height:0;overflow:hidden;transition:max-height .3s ease,padding .3s ease;padding:0; }
.faq-item.open .faq-a { max-height:160px;padding-bottom:18px; }

/* ─── WATERCOLOR REVEAL ─── */
#wc-overlay {
  position: fixed;
  inset: 0;
  z-index: 99999;
  pointer-events: none;
}
#wc-canvas {
  display: block;
  width: 100%;
  height: 100%;
  filter: url(#wc-ink);
}

    /* ─── TESTIMONIALS ─── */
    .testimonials-section { background: var(--bg); overflow: hidden; position: relative; padding-bottom:0 !important; }
    .testimonials-section .testi-bg { position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center top;z-index:0; }
    .testimonials-section .container,
    .testimonials-section .testi-v2-cols { position:relative;z-index:1; }
    .testi-v2-header { display:flex;flex-direction:column;align-items:center;text-align:center;max-width:540px;margin:0 auto 56px; }
    .testi-v2-h2 { font-size:clamp(30px,4vw,46px);font-weight:800;letter-spacing:-.025em;line-height:1.1;color:var(--text);margin-bottom:14px;white-space:nowrap; }
    .testi-v2-cols { display:flex;justify-content:center;gap:20px;max-height:580px;overflow:hidden;padding:0 24px;-webkit-mask-image:linear-gradient(to bottom,transparent,black 12%,black 100%);mask-image:linear-gradient(to bottom,transparent,black 12%,black 100%); }
    .testi-v2-col { display:flex;flex-direction:column;flex:0 0 300px; }
    @keyframes testiScroll { 0%{transform:translateY(0);} 100%{transform:translateY(-50%);} }
    .testi-v2-track { display:flex;flex-direction:column;gap:20px;animation:testiScroll linear infinite; }
    .testi-v2-col:nth-child(1) .testi-v2-track { animation-duration:22s; }
    .testi-v2-col:nth-child(2) .testi-v2-track { animation-duration:28s; }
    .testi-v2-col:nth-child(3) .testi-v2-track { animation-duration:24s; }
