(function() {
    document.querySelectorAll('.nav-item.has-mega').forEach(function(item) {
      var panel = item.querySelector('.mega-panel');
      var timer;
      function openMenu()  { clearTimeout(timer); item.classList.add('mega-open'); }
      function closeMenu() { timer = setTimeout(function() { item.classList.remove('mega-open'); }, 120); }
      item.addEventListener('mouseenter', openMenu);
      item.addEventListener('mouseleave', closeMenu);
      if (panel) {
        panel.addEventListener('mouseenter', openMenu);
        panel.addEventListener('mouseleave', closeMenu);
      }
    });
  })();

var activeCategory = 'all';
  var currentPage = 1;
  var CARDS_PER_PAGE = 6;

  function setFilter(cat, btn) {
    activeCategory = cat;
    currentPage = 1;
    document.querySelectorAll('.blog-filter-btn').forEach(function(b) { b.classList.remove('active'); });
    btn.classList.add('active');
    renderCards();
  }

  function renderCards() {
    var searchQuery = document.getElementById('blog-search-input').value.toLowerCase().trim();
    var allCards = Array.from(document.querySelectorAll('#blog-grid .blog-card'));

    // Filter
    var filtered = allCards.filter(function(card) {
      var cat = card.getAttribute('data-category');
      var title = card.getAttribute('data-title').toLowerCase();
      var excerpt = card.querySelector('.blog-card-excerpt').textContent.toLowerCase();
      var catMatch = (activeCategory === 'all') || (cat === activeCategory);
      var searchMatch = !searchQuery || title.indexOf(searchQuery) !== -1 || excerpt.indexOf(searchQuery) !== -1;
      return catMatch && searchMatch;
    });

    // Hide all first
    allCards.forEach(function(c) { c.style.display = 'none'; });

    // Paginate
    var totalPages = Math.max(1, Math.ceil(filtered.length / CARDS_PER_PAGE));
    if (currentPage > totalPages) currentPage = totalPages;
    var start = (currentPage - 1) * CARDS_PER_PAGE;
    filtered.slice(start, start + CARDS_PER_PAGE).forEach(function(c) { c.style.display = ''; });

    // No results
    document.getElementById('blog-no-results').style.display = filtered.length === 0 ? 'block' : 'none';

    // Render pagination
    renderPagination(totalPages);
  }

  function goToPage(p) {
    currentPage = p;
    renderCards();
    document.querySelector('.blog-section').scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  function renderPagination(totalPages) {
    var el = document.getElementById('blog-pagination');
    if (totalPages <= 1) { el.innerHTML = ''; return; }
    var html = '';
    html += '<button class="blog-page-arrow" onclick="goToPage(' + (currentPage - 1) + ')"' + (currentPage === 1 ? ' disabled' : '') + '>‹</button>';
    for (var i = 1; i <= totalPages; i++) {
      html += '<button class="blog-page-btn' + (i === currentPage ? ' active' : '') + '" onclick="goToPage(' + i + ')">' + i + '</button>';
    }
    html += '<button class="blog-page-arrow" onclick="goToPage(' + (currentPage + 1) + ')"' + (currentPage === totalPages ? ' disabled' : '') + '>›</button>';
    el.innerHTML = html;
  }

  // Init on load
  renderCards();

  // Make all blog cards clickable
  document.querySelectorAll('#blog-grid .blog-card').forEach(function(card) {
    card.style.cursor = 'pointer';
    card.addEventListener('click', function() {
      location.href = '/blog-post';
    });
  });

function toggleFaq(el) {
    var item = el.parentElement;
    var icon = el.querySelector('.faq-icon');
    var isOpen = item.classList.contains('open');
    document.querySelectorAll('.faq-item').forEach(function(i) {
      i.classList.remove('open');
      i.querySelector('.faq-icon').textContent = '+';
    });
    if (!isOpen) { item.classList.add('open'); icon.textContent = '−'; }
  }

(function () {
  var overlay = document.getElementById('wc-overlay');
  var canvas  = document.getElementById('wc-canvas');
  var turb    = document.getElementById('wc-turb');

  if (turb) turb.setAttribute('seed', Math.floor(Math.random() * 120) + 1);

  var ctx = canvas.getContext('2d');
  var W, H;

  function resize() {
    W = canvas.width  = window.innerWidth;
    H = canvas.height = window.innerHeight;
  }
  resize();
  window.addEventListener('resize', resize);

  function easeOut(t) { return 1 - Math.pow(1 - t, 1.8); }

  function maxCornerDist(ox, oy) {
    return Math.max(
      Math.hypot(ox, oy),
      Math.hypot(W - ox, oy),
      Math.hypot(ox, H - oy),
      Math.hypot(W - ox, H - oy)
    );
  }

  var drops = [
    { fx: 0.22, fy: 0.20, reach: 1.35, lag: 0.00 },
    { fx: 0.78, fy: 0.32, reach: 1.30, lag: 0.06 },
    { fx: 0.48, fy: 0.78, reach: 1.25, lag: 0.10 }
  ];

  var DURATION  = 3400;
  var startTime = null;

  function frame(ts) {
    if (!startTime) startTime = ts;
    var progress = Math.min((ts - startTime) / DURATION, 1);

    ctx.globalCompositeOperation = 'source-over';
    ctx.globalAlpha = 1;
    ctx.fillStyle   = '#F7F7F4';
    ctx.fillRect(0, 0, W, H);

    ctx.globalCompositeOperation = 'destination-out';

    drops.forEach(function (d) {
      var t  = Math.max(0, Math.min((progress - d.lag) / (1 - d.lag), 1));
      var e  = easeOut(t);
      var ox = d.fx * W;
      var oy = d.fy * H;
      var r  = e * maxCornerDist(ox, oy) * d.reach;
      if (r < 1) return;

      var g = ctx.createRadialGradient(ox, oy, r * 0.30, ox, oy, r);
      g.addColorStop(0.00, 'rgba(0,0,0,1)');
      g.addColorStop(0.50, 'rgba(0,0,0,0.98)');
      g.addColorStop(0.70, 'rgba(0,0,0,0.85)');
      g.addColorStop(0.82, 'rgba(0,0,0,0.55)');
      g.addColorStop(0.92, 'rgba(0,0,0,0.20)');
      g.addColorStop(1.00, 'rgba(0,0,0,0)');

      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(ox, oy, r, 0, Math.PI * 2);
      ctx.fill();
    });

    ctx.globalCompositeOperation = 'source-over';
    ctx.globalAlpha = 1;

    if (progress < 1) {
      requestAnimationFrame(frame);
    } else {
      overlay.style.transition = 'opacity 0.45s ease';
      overlay.style.opacity    = '0';
      setTimeout(function () { overlay.remove(); }, 550);
    }
  }

  requestAnimationFrame(frame);
})();
